import { FormControl, FormGroup, Validators } from '@angular/forms';

export function QrCreateForm(): FormGroup {
  return new FormGroup({
    amount: new FormControl('', [
      Validators.required,
      Validators.pattern(/^\d+$/),
    ]),
    noOfCoupans: new FormControl('', [
      Validators.required,
      Validators.pattern(/^\d+$/),
    ]),
  });
}
